-- Additive migration; Netlify owns the surrounding transaction.
CREATE TABLE IF NOT EXISTS "ServiceDefinition" ("id" TEXT PRIMARY KEY,"kind" TEXT NOT NULL,"body" JSONB NOT NULL,"version" INTEGER NOT NULL DEFAULT 1,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "ServiceDefinition_kind_idx" ON "ServiceDefinition"("kind");
CREATE TABLE IF NOT EXISTS "ServiceRequest" ("id" TEXT PRIMARY KEY,"customerId" TEXT NOT NULL,"offeringId" TEXT NOT NULL,"status" TEXT NOT NULL,"cityId" TEXT NOT NULL,"startAt" TIMESTAMPTZ(3) NOT NULL,"endAt" TIMESTAMPTZ(3) NOT NULL,"body" JSONB NOT NULL,"version" INTEGER NOT NULL DEFAULT 1,"idempotencyKey" TEXT NOT NULL UNIQUE,"requestHash" TEXT NOT NULL,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ServiceRequest_interval_check" CHECK ("endAt">"startAt"));
CREATE INDEX IF NOT EXISTS "ServiceRequest_customerId_createdAt_idx" ON "ServiceRequest"("customerId","createdAt");
CREATE INDEX IF NOT EXISTS "ServiceRequest_status_startAt_idx" ON "ServiceRequest"("status","startAt");
CREATE INDEX IF NOT EXISTS "ServiceRequest_offeringId_startAt_idx" ON "ServiceRequest"("offeringId","startAt");
CREATE TABLE IF NOT EXISTS "ServiceReservation" ("id" TEXT PRIMARY KEY,"requestId" TEXT NOT NULL,"resourceKey" TEXT NOT NULL,"startAt" TIMESTAMPTZ(3) NOT NULL,"endAt" TIMESTAMPTZ(3) NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,CONSTRAINT "ServiceReservation_requestId_resourceKey_key" UNIQUE("requestId","resourceKey"),CONSTRAINT "ServiceReservation_interval_check" CHECK ("endAt">"startAt"));
CREATE INDEX IF NOT EXISTS "ServiceReservation_resourceKey_active_startAt_endAt_idx" ON "ServiceReservation"("resourceKey","active","startAt","endAt");
CREATE TABLE IF NOT EXISTS "ServiceRequestEvent" ("id" TEXT PRIMARY KEY,"requestId" TEXT NOT NULL,"actorId" TEXT NOT NULL,"action" TEXT NOT NULL,"body" JSONB NOT NULL,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "ServiceRequestEvent_requestId_createdAt_idx" ON "ServiceRequestEvent"("requestId","createdAt");
CREATE TABLE IF NOT EXISTS "ServiceFinanceEntry" ("id" TEXT PRIMARY KEY,"requestId" TEXT NOT NULL,"kind" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'PENDING',"amount" INTEGER NOT NULL CHECK ("amount">0),"reference" TEXT NOT NULL UNIQUE,"makerId" TEXT NOT NULL,"checkerId" TEXT,"body" JSONB NOT NULL,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"updatedAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX IF NOT EXISTS "ServiceFinanceEntry_requestId_status_idx" ON "ServiceFinanceEntry"("requestId","status");
CREATE TABLE IF NOT EXISTS "ServiceInbox" ("id" TEXT PRIMARY KEY,"userId" TEXT NOT NULL,"requestId" TEXT NOT NULL,"event" TEXT NOT NULL,"dueAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"readAt" TIMESTAMPTZ(3),"body" JSONB NOT NULL,"createdAt" TIMESTAMPTZ(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,CONSTRAINT "ServiceInbox_userId_requestId_event_key" UNIQUE("userId","requestId","event"));
CREATE INDEX IF NOT EXISTS "ServiceInbox_userId_dueAt_idx" ON "ServiceInbox"("userId","dueAt");
CREATE UNIQUE INDEX IF NOT EXISTS "ServiceDefinition_serviceId_unique" ON "ServiceDefinition" (("body"->>'serviceId')) WHERE "kind"='OFFERING' AND "body"->>'serviceId' IS NOT NULL;
